// OWNER: INTEGRATOR
// FROZEN shared contract. Feature branches do not edit this file.
// Need a new event or field? Note it in your handoff; the integrator adds it.
//
// Story mode and checkpoints are intentionally absent (course override: hardcore).
// Cross-module calls go through the bus, ctx, or pure data imports
// (this file, balance_*.js, lines.js). Do not import another workstream's runtime.

/** @typedef {import('three').Vector3} Vector3 */
/** @typedef {import('three').Scene} Scene */
/** @typedef {import('three').PerspectiveCamera} PerspectiveCamera */
/** @typedef {import('three').WebGLRenderer} WebGLRenderer */
/** @typedef {import('three').Object3D} Object3D */

export const BUILD_TAG = 'skeleton';

/** @enum {string} */
export const TEAMS = Object.freeze({
  PLAYER: 'player',
  ALLY: 'ally',
  BOSS: 'boss',
  NEUTRAL: 'neutral',
});

/**
 * Game flow. `paused` overlays a fight; resume returns to `fight`.
 * There is no story-mode state and no checkpoint state.
 * @enum {string}
 */
export const GAME_STATES = Object.freeze({
  TITLE: 'title',
  DISCLAIMER: 'disclaimer',
  SELECT: 'select',
  FIGHT: 'fight',
  BANNED: 'banned',
  THEATER: 'theater',
  CREDITS: 'credits',
  PAUSED: 'paused',
});

/**
 * Bus event names. Payload shapes are in the typedefs below.
 * Values are the stable strings on the wire — do not rename them.
 */
export const EVENTS = Object.freeze({
  /** @type {'state_change'} payload StateChange */
  STATE_CHANGE: 'state_change',
  /** @type {'fight_start'} payload {charId:string} */
  FIGHT_START: 'fight_start',
  /** @type {'fight_reset'} payload {charId:string} */
  FIGHT_RESET: 'fight_reset',
  /** @type {'phase_change'} payload PhaseChange */
  PHASE_CHANGE: 'phase_change',
  /** @type {'hit'} payload HitEvent */
  HIT: 'hit',
  /** @type {'hit_stop'} payload {ms:number} */
  HIT_STOP: 'hit_stop',
  /** @type {'flask_used'} payload FlaskEvent */
  FLASK_USED: 'flask_used',
  /** @type {'flask_interrupted'} payload FlaskEvent */
  FLASK_INTERRUPTED: 'flask_interrupted',
  /** @type {'perfect_guard'} payload {id?:string} */
  PERFECT_GUARD: 'perfect_guard',
  /** @type {'guard_start'} payload {id:string} */
  GUARD_START: 'guard_start',
  /** @type {'guard_end'} payload {id:string} */
  GUARD_END: 'guard_end',
  /** @type {'player_death'} payload PlayerDeath */
  PLAYER_DEATH: 'player_death',
  /** @type {'player_attack'} payload {id:string, name:string} */
  PLAYER_ATTACK: 'player_attack',
  /** @type {'skill_used'} payload {id:string, name:string} */
  SKILL_USED: 'skill_used',
  /** @type {'roll_start'} payload {id:string} */
  ROLL_START: 'roll_start',
  /** @type {'roll_end'} payload {id:string} */
  ROLL_END: 'roll_end',
  /** @type {'ally_down'} payload {id:string} */
  ALLY_DOWN: 'ally_down',
  /** @type {'ally_revive'} payload {id:string} */
  ALLY_REVIVE: 'ally_revive',
  /** @type {'ally_speech'} payload {id:string, text:{zh:string, en:string}} */
  ALLY_SPEECH: 'ally_speech',
  /** @type {'boss_hp'} payload BossHp */
  BOSS_HP: 'boss_hp',
  /** @type {'boss_attack'} payload {name:string, phase:number} */
  BOSS_ATTACK: 'boss_attack',
  /** @type {'telegraph_start'} payload TelegraphEvent */
  TELEGRAPH_START: 'telegraph_start',
  /** @type {'telegraph_resolve'} payload TelegraphEvent */
  TELEGRAPH_RESOLVE: 'telegraph_resolve',
  /** @type {'ending_trigger'} payload {id:'A'|'B'} */
  ENDING_TRIGGER: 'ending_trigger',
  /** @type {'theater_shot'} payload {endingId:string, id:string, index:number} */
  THEATER_SHOT: 'theater_shot',
  /** @type {'theater_done'} payload {endingId:string} */
  THEATER_DONE: 'theater_done',
  /** @type {'distill_progress'} payload {value:number} displayed 0–100, not the true ratio */
  DISTILL_PROGRESS: 'distill_progress',
  /** @type {'dario_line'} payload {event:string, text:{zh:string, en:string}, priority:number} */
  DARIO_LINE: 'dario_line',
  /** @type {'camera_shake'} payload {intensity:number, duration?:number} */
  CAMERA_SHAKE: 'camera_shake',
  /** @type {'pause'} payload {from:string} */
  PAUSE: 'pause',
  /** @type {'resume'} payload {} */
  RESUME: 'resume',
  /** @type {'select_confirm'} payload {charId:string} */
  SELECT_CONFIRM: 'select_confirm',
  /** @type {'retry'} payload {} */
  RETRY: 'retry',
  /** @type {'banner'} payload {phase:number, zh:string, en:string} */
  BANNER: 'banner',
  /** @type {'input_lock'} payload {locked:boolean, state:string} */
  INPUT_LOCK: 'input_lock',
  /** @type {'god_mode'} payload {enabled:boolean} */
  GOD_MODE: 'god_mode',
  /** @type {'lock_on'} payload {enabled:boolean} */
  LOCK_ON: 'lock_on',
  /** @type {'skill_silence'} payload {{duration:number, until:number, zh:string, en:string}} */
  SKILL_SILENCE: 'skill_silence',
});

/**
 * @typedef {Object} StateChange
 * @property {string|null} from
 * @property {string} to
 */

/**
 * @typedef {Object} PhaseChange
 * @property {1|2|3} phase
 * @property {number} from
 */

/**
 * @typedef {Object} HitEvent
 * @property {Actor|string|null} src
 * @property {Actor} dst
 * @property {number} dmg      Incoming amount after debug multipliers, before armor / guard.
 * @property {number} applied  Amount actually removed from hp.
 * @property {boolean} heavy
 */

/**
 * @typedef {Object} FlaskEvent
 * @property {string} type   'rtx5090' | 'h200' | 'b200'
 * @property {string} [id]
 */

/**
 * @typedef {Object} PlayerDeath
 * @property {number} phase  Boss phase at the moment of death.
 * @property {string} [id]
 */

/**
 * @typedef {Object} BossHp
 * @property {number} ratio  hp / maxHp, 0–1
 * @property {number} hp
 * @property {number} maxHp
 */

/**
 * @typedef {Object} TelegraphEvent
 * @property {string|null} attack
 * @property {TelegraphShape} shape
 * @property {string} id
 * @property {number} [duration]
 */

/**
 * Damage request passed into Actor.takeDamage.
 * Callers should not build this themselves — use applyHit() in core/combat.js,
 * which fills multipliers, emits EVENTS.hit, and then calls takeDamage.
 * @typedef {Object} DamageInfo
 * @property {number} dmg
 * @property {boolean} [heavy]
 * @property {Actor|string|null} [src]
 * @property {boolean} [ignoreInvuln]
 * @property {boolean} [noKnockback]
 * @property {boolean} [noStun]
 * @property {string|number} [attackId]  Same id shares the 0.6 s hurt immunity on the player.
 */

/**
 * @typedef {Object} Actor
 * @property {string} id
 * @property {'player'|'ally'|'boss'|'neutral'} team
 * @property {Vector3} position
 * @property {number} hp
 * @property {number} maxHp
 * @property {number} radius
 * @property {boolean} alive
 * @property {boolean} invulnerable
 * @property {Object3D|null} sprite   Billboard mesh, if any.
 * @property {(info: DamageInfo) => number} takeDamage  Returns hp actually removed.
 */

/**
 * @typedef {Actor & {
 *   phase: 1|2|3,
 *   lockHpAt25: boolean,
 *   height: number,
 *   damageMul: number,
 *   setPhase: (phase: 1|2|3, opts?: {noInvuln?: boolean, silent?: boolean}) => void,
 * }} BossActor
 */

/** @typedef {'circle'|'sector'|'line'|'ring'|'fullscreen'} TelegraphShape */

/**
 * Ground warning. Angles are radians unless `arcDeg` is set.
 * `origin` may be a Vector3 or `{x, z}`. `direction` is planar `{x, z}` (or a Vector3).
 * Hit testing uses the horizontal XZ plane and ignores Y.
 *
 * @typedef {Object} TelegraphSpec
 * @property {string} [id]
 * @property {string} [attack]
 * @property {TelegraphShape} shape
 * @property {number} duration          Seconds until the fill completes and onResolve runs.
 * @property {Vector3|{x:number, z:number}} [origin]
 * @property {Vector3|{x:number, z:number}} [direction]  For sector (bisector) and line (along).
 * @property {number} [radius]          circle / sector outer / ring outer. Default 2.
 * @property {number} [innerRadius]     ring hole. Default 0.
 * @property {number} [arc]             sector width in radians.
 * @property {number} [arcDeg]          sector width in degrees (used when `arc` is omitted).
 * @property {number} [length]          line length in meters.
 * @property {number} [width]           line width in meters.
 * @property {Array<{x:number, z:number, radius:number}>} [safeZones]  fullscreen only; inside these is a miss.
 * @property {number} [damage]
 * @property {boolean} [heavy]
 * @property {(ctx: GameContext, telegraph: TelegraphHandle) => void} [onResolve]
 */

/**
 * @typedef {Object} TelegraphHandle
 * @property {string} id
 * @property {TelegraphSpec} spec   Normalized copy (radians, plain {x,z}).
 * @property {number} elapsed
 * @property {number} duration
 * @property {() => void} cancel
 * @property {(point: Vector3|{x:number, z:number}) => boolean} contains
 */

/**
 * @typedef {Object} BillboardOptions
 * @property {string} assetId
 * @property {string} label
 * @property {string} color          CSS color for the placeholder body.
 * @property {string} [accent]
 * @property {number} height         World meters.
 * @property {number} [width]
 * @property {'front'|'back'} [facing]
 * @property {Actor} [owner]
 */

/**
 * @typedef {Object} Billboard
 * @property {Object3D} mesh
 * @property {Object3D|null} shadow
 * @property {number} height
 * @property {number} width
 * @property {Actor|null} owner
 * @property {number} flash          Seconds of hit-flash remaining.
 */

/**
 * @typedef {Object} SpriteAPI
 * @property {(opts: BillboardOptions) => Billboard} createBillboard
 * @property {(billboard: Billboard|null) => void} destroyBillboard
 * @property {(ctx: GameContext, dt: number) => void} present
 */

/**
 * @typedef {Object} TelegraphAPI
 * @property {(ctx: GameContext, spec: TelegraphSpec) => TelegraphHandle} spawn
 * @property {(ctx: GameContext, dt: number) => void} update
 * @property {(ctx: GameContext) => void} reset
 * @property {() => TelegraphHandle[]} active
 */

/**
 * @typedef {Object} VfxAPI
 * @property {(ctx: GameContext, dt: number) => void} update
 * @property {(ctx: GameContext, dt: number) => void} present
 * @property {(ctx: GameContext) => void} reset
 */

/**
 * @typedef {Object} CameraAPI
 * @property {(ctx: GameContext, forward: Vector3, right: Vector3) => void} planarBasis
 * @property {(ctx: GameContext, dt: number) => void} update
 */

/**
 * Runtime services hung off ctx.world. Owners replace the bodies, not these names.
 * @typedef {Object} WorldAPI
 * @property {number} radius
 * @property {(pos: Vector3, pad?: number) => void} clamp
 * @property {(zh: string, en: string) => void} setHolo
 * @property {SpriteAPI} sprites
 * @property {TelegraphAPI} telegraph
 * @property {VfxAPI} vfx
 * @property {CameraAPI} camera
 */

/**
 * @typedef {Object} DebugFlags
 * @property {boolean} godMode
 * @property {boolean} showHitboxes
 * @property {number} playerDmgMul
 * @property {number} bossDmgMul
 * @property {number} allyDmgMul
 * @property {number} timeScale
 * @property {number} camDistance     Meters behind the shoulder. Default 5.5.
 * @property {number} camHeight       Default 2.2.
 * @property {number} camSide         Right offset. Default 0.9.
 * @property {number} camFov          Default 60.
 */

/**
 * @typedef {Object} StateMachine
 * @property {string} current
 * @property {string|null} previous
 * @property {(next: string) => void} set
 */

/**
 * @typedef {Object} InputAPI
 * @property {(name: string) => boolean} pressed  Edge, true for this frame's readers. Not auto-consuming.
 * @property {(name: string) => boolean} held
 * @property {() => boolean} typing               Focus is in a form field.
 * @property {{x:number, y:number, dx:number, dy:number, locked:boolean, onUi:boolean}} pointer
 * @property {(fn: () => boolean) => void} setPointerLock
 * @property {() => void} endFrame
 */

/**
 * HTMLAudio for files. The AudioContext used for missing-file beeps is created
 * only after unlock() (a user gesture). playVo ducks music. Short sfx trim
 * themselves; pass maxDuration: 0 to keep a long cue.
 *
 * @typedef {Object} AudioAPI
 * @property {(id: string, opts?: {loop?: boolean, volume?: number, rate?: number, maxDuration?: number, fadeOut?: number}) => void} playSfx
 * @property {(id: string, fade?: number|{fade?: number}) => void} playBgm
 * @property {(fade?: number|{fade?: number}) => void} stopBgm
 * @property {(id: string, opts?: {volume?: number, duck?: number}) => {duration: number, promise: Promise<number>}} playVo
 * @property {() => void} stopVo
 * @property {(id?: string, fade?: number|{fade?: number}) => void} stopSfx
 * @property {(amount?: number|boolean) => void} duck
 * @property {(partial: {master?: number, music?: number, sfx?: number, vo?: number}) => void} setVolume
 * @property {() => {master:number, music:number, sfx:number, vo:number}} getVolume
 * @property {() => void} unlock
 */

/**
 * @typedef {Object} TimeAPI
 * @property {number} fixedDt
 * @property {number} timeScale
 * @property {number} hitStop       Seconds of sim freeze remaining.
 * @property {number} elapsed       Sim seconds advanced (scaled, not during pause / hit-stop).
 * @property {number} unscaled      Real seconds since boot.
 * @property {number} lastRaw
 * @property {(ms: number) => void} requestHitStop
 * @property {(scale: number) => void} setScale
 * @property {() => void} reset
 */

/**
 * @typedef {Object} AssetAPI
 * @property {(id: string) => string|null} get
 * @property {(id: string, fallbackDrawFn?: Function) => import('three').Texture} texture
 * @property {object} config
 */

/**
 * The singleton every module receives. Main owns construction.
 * Feature code reads other actors and services off ctx; it does not import their modules
 * unless they are pure data or the same workstream.
 *
 * @typedef {Object} GameContext
 * @property {Scene} scene
 * @property {PerspectiveCamera} camera
 * @property {WebGLRenderer} renderer
 * @property {import('./bus.js').EventBus} bus
 * @property {InputAPI} input
 * @property {AudioAPI} audio
 * @property {TimeAPI} time
 * @property {AssetAPI} assets
 * @property {Actor|null} player
 * @property {BossActor|null} boss
 * @property {Actor[]} allies
 * @property {WorldAPI} world
 * @property {StateMachine} state
 * @property {DebugFlags} debug
 * @property {string|null} selectedChar
 * @property {boolean} lockOn
 * @property {'A'|'B'|null} endingActive
 * @property {number} distill            Displayed distill percent (lies on purpose; endings zero it).
 * @property {number} endingDistill      Snapshot at the moment an ending starts.
 * @property {{skillSilence?: number, skillSilenceUntil?: number, contentPolicySilence?: boolean}} [flags]
 *           Content-policy silence. skillSilence is seconds remaining and the source of truth.
 * @property {{A?:boolean, B?:boolean}} endingsUnlocked
 */

/**
 * Every gameplay module exports this trio. Main calls them.
 * `update` for sim modules receives a fixed sim dt (scaled, never during hit-stop).
 * `update` for UI modules receives the raw frame dt. See ARCHITECTURE.md.
 *
 * @typedef {Object} GameModule
 * @property {(ctx: GameContext) => void} init
 * @property {(ctx: GameContext, dt: number) => void} update
 * @property {(ctx: GameContext) => void} reset
 */
